    INSERT INTO cloud_changes (tbl, pk, op) SELECT 'stock_movements', OLD.id, 'd' WHERE OLD.id IS NOT NEW.id;
    INSERT INTO cloud_changes (tbl, pk, op) VALUES ('stock_movements', NEW.id, 'u');
END;
CREATE TRIGGER IF NOT EXISTS cloud_stock_movements_del AFTER DELETE ON stock_movements WHEN (SELECT value FROM app_settings WHERE key = 'cloud.enabled') = '1'
BEGIN INSERT INTO cloud_changes (tbl, pk, op) VALUES ('stock_movements', OLD.id, 'd'); END;

